import { tags } from "typia";

/**
 * Generic pagination configuration used by analytics request DTOs.
 *
 * This model defines how analytics endpoints limit the number of aggregated
 * rows returned per call and how clients request specific pages of results.
 *
 * It supports both classic page/size pagination and cursor-based continuation
 * via an opaque cursor string, enabling scalable traversal of large result
 * sets.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IAnalyticsPagination = {
  /**
   * 1-based page index used for classic offset pagination.
   *
   * When both `page` and `size` are provided and `cursor` is not set, the
   * analytics engine computes an offset from `(page - 1) * size` and returns
   * the requested slice.
   *
   * If omitted in favor of `cursor`, the backend switches to cursor-based
   * pagination semantics.
   */
  page?: (number & tags.Type<"int32"> & tags.Minimum<1>) | undefined;

  /**
   * Maximum number of analytics rows to return in a single page.
   *
   * This value should remain within server-enforced limits to prevent
   * excessively large responses. Typical limits range between 50 and 1000
   * rows depending on environment.
   *
   * When omitted, the backend applies a default page size.
   */
  size?: (number & tags.Type<"int32"> & tags.Minimum<1>) | undefined;

  /**
   * Opaque continuation token representing the current position within the
   * analytics result set.
   *
   * When provided, the analytics engine ignores `page` and uses the cursor to
   * fetch the next page of results. Callers should treat the token as an
   * implementation detail and not attempt to parse or construct it manually.
   */
  cursor?: string | undefined;
};
